'use strict';

const debug = require('debug')('antvip#checksum');

exports.hashVipDomain = hashVipDomain;
exports.hashRealNodes = hashRealNodes;
exports.hashRealNode = hashRealNode;
exports.hashBool = hashBool;
exports.hashArray = hashArray;
exports.hashString = hashString;

exports.buildVipDomainName2ChecksumMap = vipDomains => {
  const checksumMap = {};
  for (const domainName of vipDomains.keys()) {
    const vipDomain = vipDomains.get(domainName);
    checksumMap[domainName] = exports.hashVipDomain(vipDomain);
  }
  debug('checksumMap: %j', checksumMap);
  return checksumMap;
};

function hashVipDomain(vipDomain) {
  if (!vipDomain) {
    return 'N';
  }

  let result = 1;
  /* eslint-disable */
  result = (31 * result + hashString(vipDomain.name)) & 0xFFFFFFFF;
  result = (31 * result + vipDomain.protectThreshold) & 0xFFFFFFFF;
  result = (31 * result + vipDomain.healthCheckDefaultPort) & 0xFFFFFFFF;
  result = (31 * result + hashRealNodes(vipDomain.realNodes)) & 0xFFFFFFFF;
  /* eslint-enable */
  return result + '';
}

function hashRealNodes(realNodes) {
  if (!realNodes) return 0;
  let result = 1;
  for (const realNode of realNodes) {
    /* eslint-disable */
    result = (31 * result + hashRealNode(realNode)) & 0xFFFFFFFF;
    /* eslint-enable */
  }
  return result;
}

function hashRealNode(realNode) {
  if (!realNode) return 0;
  let result = 1;
  /* eslint-disable */
  result = (31 * result + (typeof realNode.available !== 'boolean' ? 0 : hashBool(realNode.available))) & 0xFFFFFFFF;
  result = (31 * result + hashString(realNode.ip)) & 0xFFFFFFFF;
  result = (31 * result + realNode.weight) & 0xFFFFFFFF;
  result = (31 * result + (realNode.healthCheckPort || 0)) & 0xFFFFFFFF;
  /* eslint-enable */
  return result;
}

function hashBool(value) {
  return value ? 1231 : 1237;
}

function hashArray(arr) {
  if (!arr || arr.length === 0) {
    // 'N' 代表紧急的 checksum，自身没有数据时使用它
    return 'N';
  }

  let hash = 1;
  for (const str of arr) {
    /* eslint-disable */
    hash = (31 * hash + hashString(str)) & 0xFFFFFFFF;
    /* eslint-enable */
  }
  return hash + '';
}

function hashString(str) {
  str = str || '';
  let hash = 0;
  if (!str) return hash;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    /* eslint-disable */
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
    /* eslint-enable */
  }
  return hash;
}
